function timelineCourtStrip(g,p){
 const records=C.ordered(g),period=records.filter(e=>C.periodKey(e.period)===p.key),start=period.find(e=>e.code==='period_start'),end=period.find(e=>e.code==='period_end');
 const strip=el('div',{class:'timeline-court-strip','aria-label':p.label+' court time'});
 const low=start?Date.parse(C.occurred(start)):NaN,high=end?Date.parse(C.occurred(end)):NaN;
 if(!Number.isFinite(low)||!Number.isFinite(high)||high<=low){strip.classList.add('is-unknown');strip.setAttribute('aria-label',p.label+' court time incomplete');strip.title='Court time incomplete';return strip}
 let cursor=low,on=C.rawOnCourt(g,low),segments=[];
 for(const e of period){const t=Date.parse(C.occurred(e));if(!['in','out'].includes(e.code)||t<low||t>high)continue;if(t>cursor)segments.push({on,seconds:(t-cursor)/1000});cursor=t;on=e.code==='in'}
 if(high>cursor)segments.push({on,seconds:(high-cursor)/1000});
 for(const part of segments){const name=part.on?'On court':'Bench',span=el('span',{class:part.on?'is-court':'is-bench',title:name+' · '+elapsedText(part.seconds),'aria-label':name+' · '+elapsedText(part.seconds)});span.style.flex=part.seconds+' 1 0';strip.append(span)}return strip
}
function reportTimeline(g){const details=reportTimelineOriginal(g);const periods=C.periodOptions(g);details.querySelectorAll('.timeline-period').forEach((col,i)=>{const p=periods[i],records=C.ordered(g).filter(e=>C.periodKey(e.period)===p.key),start=records.find(e=>e.code==='period_start'),end=records.find(e=>e.code==='period_end'),low=start?Date.parse(C.occurred(start)):NaN,high=end?Date.parse(C.occurred(end)):NaN;if(Number.isFinite(low)&&high>low){col.querySelector('.timeline-bars').classList.add('has-elapsed-time');col.querySelectorAll('[data-timeline-event]').forEach(b=>{const e=records.find(e=>e.id===b.dataset.timelineEvent),t=Date.parse(C.occurred(e));if(!courtBeforeRecord(g,e)){b.remove();return}const percent=Math.max(0,Math.min(100,(t-low)/(high-low)*100));b.style.left='clamp(0px, calc('+percent+'% - 7px), calc(100% - 14px))';b.dataset.timelinePosition=percent});const bars=col.querySelector('.timeline-bars');bars.addEventListener('click',event=>{if(event.target.closest('button'))return;timelinePick(g,bars,event.clientX)})}col.insertBefore(timelineCourtStrip(g,p),col.querySelector('.timeline-period-label'))});details.querySelector('.timeline-note').textContent='Plays by elapsed period time · gaps show no recorded activity · tap a play to edit';details.append(el('div',{class:'timeline-court-legend'},el('span',{},el('i',{class:'is-court'}),'On court'),el('span',{},el('i',{class:'is-bench'}),'Bench'),el('small',{},'Bottom strip · elapsed time')));return details}

