async function sound(test=false){if(!db.prefs.sound)return false;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Audio unavailable');if(!audio||audio.state==='closed')audio=new Audio();if(audio.state!=='running')await audio.resume();if(audio.state!=='running')throw Error('Audio blocked');const at=audio.currentTime+.01,o=audio.createOscillator(),gain=audio.createGain();o.type='sine';o.frequency.setValueAtTime(740,at);o.frequency.exponentialRampToValueAtTime(520,at+.11);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.16,at+.008);gain.gain.exponentialRampToValueAtTime(.001,at+.13);o.connect(gain);gain.connect(audio.destination);o.start(at);o.stop(at+.14);o.onended=()=>{o.disconnect();gain.disconnect()};return true}catch{if(test)announce('Sound unavailable. Check device volume and browser audio settings.');return false}}
